Expression<Func<int, int>> e = x => 2 + 3 + x;
var folded = Solution.FoldExpr(e);
var f = folded.Compile();
Cj.Eq(f(4), 9, "(2+3)+x must fold to 5+x");
int constAdds = 0;
new Visitor(v =>
{
    if (v is BinaryExpression b && v.NodeType == ExpressionType.Add
        && b.Left is ConstantExpression && b.Right is ConstantExpression) constAdds++;
}).Visit(folded);
Cj.Eq(constAdds, 0, "no constant-only Add remains — inner folds, then the enclosing node folds too");
